namespace BatchRenameStudio.Core;

/// <summary>Which part of the file name the steps operate on.</summary>
public enum ApplyTo
{
    Name,
    NameAndExtension,
}

/// <summary>Processing order of the files inside the folder.</summary>
public enum SortMode
{
    Name,
    Created,
    Modified,
}

public enum StepKind
{
    Replace,
    Insert,
    Remove,
    Sequence,
    Case,
    Extension,
}

/// <summary>Shared by "insert" and "sequence"; "sequence" only honours Prefix/Suffix.</summary>
public enum Position
{
    Prefix,
    Suffix,
    Index,
}

public enum CaseMode
{
    Upper,
    Lower,
    Title,
}

public enum ExtensionMode
{
    Lower,
    Upper,
    Set,
}

/// <summary>
/// One rule step. A single flat type carries the union of every op's fields; this keeps
/// JSON round-tripping and the GUI editor trivial, at the cost of a few unused fields.
/// </summary>
public sealed class RuleStep
{
    public StepKind Op { get; set; } = StepKind.Replace;

    /// <summary>GUI convenience only. Serialised as "enabled", and only when false.</summary>
    public bool Enabled { get; set; } = true;

    // replace
    public string Find { get; set; } = string.Empty;
    public string ReplaceWith { get; set; } = string.Empty;
    public bool Regex { get; set; }
    public bool IgnoreCase { get; set; }

    // insert
    public string Text { get; set; } = string.Empty;
    public Position Position { get; set; } = Position.Prefix;
    public int Index { get; set; }

    // remove
    public int From { get; set; }
    public int Count { get; set; }

    // sequence
    public string Pattern { get; set; } = "{n:000}_";
    public int Start { get; set; } = 1;
    public int Step { get; set; } = 1;

    // case
    public CaseMode CaseMode { get; set; } = CaseMode.Upper;

    // extension
    public ExtensionMode ExtensionMode { get; set; } = ExtensionMode.Lower;
    public string Value { get; set; } = string.Empty;

    public RuleStep Clone() => (RuleStep)MemberwiseClone();

    /// <summary>Single-line description used by the GUI step list.</summary>
    public string Describe()
    {
        switch (Op)
        {
            case StepKind.Replace:
                var flags = (Regex ? " regex" : "") + (IgnoreCase ? " ignore-case" : "");
                return $"replace  \"{Find}\" -> \"{ReplaceWith}\"{flags}";
            case StepKind.Insert:
                return Position == Position.Index
                    ? $"insert  \"{Text}\" at index {Index}"
                    : $"insert  \"{Text}\" as {Position.ToString().ToLowerInvariant()}";
            case StepKind.Remove:
                return $"remove  {Count} char(s) from index {From}";
            case StepKind.Sequence:
                return $"sequence  \"{Pattern}\" start {Start} step {Step} ({(Position == Position.Suffix ? "suffix" : "prefix")})";
            case StepKind.Case:
                return $"case  {CaseMode.ToString().ToLowerInvariant()}";
            case StepKind.Extension:
                return ExtensionMode == ExtensionMode.Set
                    ? $"extension  set \"{Value}\""
                    : $"extension  {ExtensionMode.ToString().ToLowerInvariant()}";
            default:
                return Op.ToString();
        }
    }
}

/// <summary>A complete rule set, i.e. the deserialised form of rules.json.</summary>
public sealed class RuleSet
{
    public ApplyTo ApplyTo { get; set; } = ApplyTo.Name;
    public SortMode Sort { get; set; } = SortMode.Name;
    public List<RuleStep> Steps { get; } = new();

    public RuleSet Clone()
    {
        var copy = new RuleSet { ApplyTo = ApplyTo, Sort = Sort };
        foreach (var s in Steps)
        {
            copy.Steps.Add(s.Clone());
        }
        return copy;
    }
}

/// <summary>Raised for malformed rule input; the CLI turns it into a non-zero exit code.</summary>
public sealed class RuleException : Exception
{
    public RuleException(string message) : base(message) { }
    public RuleException(string message, Exception inner) : base(message, inner) { }
}

