using System.Text;
using System.Text.Encodings.Web;
using System.Text.Json;

namespace BatchRenameStudio.Core;

/// <summary>
/// Hand-rolled reader/writer for rules.json. Written against <see cref="JsonDocument"/> rather
/// than attribute-driven binding so that defaults, enum spellings and error messages are all
/// explicit and match the documented contract exactly.
/// </summary>
public static class RuleSetSerializer
{
    private static readonly JsonDocumentOptions ReadOptions = new()
    {
        AllowTrailingCommas = true,
        CommentHandling = JsonCommentHandling.Skip,
    };

    private static readonly JsonWriterOptions WriteOptions = new()
    {
        Indented = true,
        Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping,
    };

    public static RuleSet ParseFile(string path)
    {
        string text;
        try
        {
            text = File.ReadAllText(path);
        }
        catch (Exception ex)
        {
            throw new RuleException($"cannot read rules file '{path}': {ex.Message}", ex);
        }
        return Parse(text);
    }

    public static RuleSet Parse(string json)
    {
        JsonDocument doc;
        try
        {
            doc = JsonDocument.Parse(json, ReadOptions);
        }
        catch (JsonException ex)
        {
            throw new RuleException($"rules file is not valid JSON: {ex.Message}", ex);
        }

        using (doc)
        {
            var root = doc.RootElement;
            if (root.ValueKind != JsonValueKind.Object)
            {
                throw new RuleException("rules file must contain a JSON object at the root.");
            }

            var set = new RuleSet
            {
                ApplyTo = ReadEnum(root, "applyTo", ApplyTo.Name, ParseApplyTo),
                Sort = ReadEnum(root, "sort", SortMode.Name, ParseSort),
            };

            if (root.TryGetProperty("steps", out var steps) && steps.ValueKind != JsonValueKind.Null)
            {
                if (steps.ValueKind != JsonValueKind.Array)
                {
                    throw new RuleException("\"steps\" must be an array.");
                }
                int i = 0;
                foreach (var element in steps.EnumerateArray())
                {
                    set.Steps.Add(ParseStep(element, i));
                    i++;
                }
            }

            return set;
        }
    }

    private static RuleStep ParseStep(JsonElement element, int index)
    {
        if (element.ValueKind != JsonValueKind.Object)
        {
            throw new RuleException($"steps[{index}] must be an object.");
        }

        if (!element.TryGetProperty("op", out var opElement) || opElement.ValueKind != JsonValueKind.String)
        {
            throw new RuleException($"steps[{index}] is missing a string \"op\".");
        }

        var step = new RuleStep
        {
            Op = ParseOp(opElement.GetString() ?? string.Empty, index),
            Enabled = ReadBool(element, "enabled", true),
        };

        switch (step.Op)
        {
            case StepKind.Replace:
                step.Find = ReadString(element, "find", string.Empty);
                step.ReplaceWith = ReadString(element, "replaceWith", string.Empty);
                step.Regex = ReadBool(element, "regex", false);
                step.IgnoreCase = ReadBool(element, "ignoreCase", false);
                break;

            case StepKind.Insert:
                step.Text = ReadString(element, "text", string.Empty);
                step.Position = ReadEnum(element, "position", Position.Prefix, ParsePosition);
                step.Index = ReadInt(element, "index", 0);
                break;

            case StepKind.Remove:
                step.From = ReadInt(element, "from", 0);
                step.Count = ReadInt(element, "count", 0);
                break;

            case StepKind.Sequence:
                step.Pattern = ReadString(element, "pattern", string.Empty);
                step.Start = ReadInt(element, "start", 1);
                step.Step = ReadInt(element, "step", 1);
                step.Position = ReadEnum(element, "position", Position.Prefix, ParsePosition);
                break;

            case StepKind.Case:
                step.CaseMode = ReadEnum(element, "mode", CaseMode.Lower, ParseCaseMode);
                break;

            case StepKind.Extension:
                step.ExtensionMode = ReadEnum(element, "mode", ExtensionMode.Lower, ParseExtensionMode);
                step.Value = ReadString(element, "value", string.Empty);
                break;
        }

        return step;
    }

    public static string Write(RuleSet set)
    {
        using var stream = new MemoryStream();
        using (var writer = new Utf8JsonWriter(stream, WriteOptions))
        {
            writer.WriteStartObject();
            writer.WriteString("applyTo", set.ApplyTo == ApplyTo.NameAndExtension ? "nameAndExtension" : "name");
            writer.WriteString("sort", set.Sort.ToString().ToLowerInvariant());
            writer.WriteStartArray("steps");
            foreach (var step in set.Steps)
            {
                WriteStep(writer, step);
            }
            writer.WriteEndArray();
            writer.WriteEndObject();
        }

        return Encoding.UTF8.GetString(stream.ToArray()).Replace("\r\n", "\n");
    }

    private static void WriteStep(Utf8JsonWriter writer, RuleStep step)
    {
        writer.WriteStartObject();
        writer.WriteString("op", step.Op.ToString().ToLowerInvariant());

        switch (step.Op)
        {
            case StepKind.Replace:
                writer.WriteString("find", step.Find);
                writer.WriteString("replaceWith", step.ReplaceWith);
                writer.WriteBoolean("regex", step.Regex);
                writer.WriteBoolean("ignoreCase", step.IgnoreCase);
                break;

            case StepKind.Insert:
                writer.WriteString("text", step.Text);
                writer.WriteString("position", step.Position.ToString().ToLowerInvariant());
                writer.WriteNumber("index", step.Index);
                break;

            case StepKind.Remove:
                writer.WriteNumber("from", step.From);
                writer.WriteNumber("count", step.Count);
                break;

            case StepKind.Sequence:
                writer.WriteString("pattern", step.Pattern);
                writer.WriteNumber("start", step.Start);
                writer.WriteNumber("step", step.Step);
                writer.WriteString("position", step.Position == Position.Suffix ? "suffix" : "prefix");
                break;

            case StepKind.Case:
                writer.WriteString("mode", step.CaseMode.ToString().ToLowerInvariant());
                break;

            case StepKind.Extension:
                writer.WriteString("mode", step.ExtensionMode.ToString().ToLowerInvariant());
                if (step.ExtensionMode == ExtensionMode.Set)
                {
                    writer.WriteString("value", step.Value);
                }
                break;
        }

        // Only emitted when it deviates from the default, so saved files stay contract-shaped.
        if (!step.Enabled)
        {
            writer.WriteBoolean("enabled", false);
        }

        writer.WriteEndObject();
    }

    // ---- primitive readers -------------------------------------------------

    private static string ReadString(JsonElement obj, string name, string fallback)
    {
        if (!obj.TryGetProperty(name, out var value))
        {
            return fallback;
        }
        return value.ValueKind switch
        {
            JsonValueKind.String => value.GetString() ?? fallback,
            JsonValueKind.Null => fallback,
            JsonValueKind.Number => value.ToString(),
            _ => throw new RuleException($"\"{name}\" must be a string."),
        };
    }

    private static bool ReadBool(JsonElement obj, string name, bool fallback)
    {
        if (!obj.TryGetProperty(name, out var value))
        {
            return fallback;
        }
        return value.ValueKind switch
        {
            JsonValueKind.True => true,
            JsonValueKind.False => false,
            JsonValueKind.Null => fallback,
            _ => throw new RuleException($"\"{name}\" must be a boolean."),
        };
    }

    private static int ReadInt(JsonElement obj, string name, int fallback)
    {
        if (!obj.TryGetProperty(name, out var value))
        {
            return fallback;
        }
        if (value.ValueKind == JsonValueKind.Null)
        {
            return fallback;
        }
        if (value.ValueKind == JsonValueKind.Number && value.TryGetInt32(out var number))
        {
            return number;
        }
        if (value.ValueKind == JsonValueKind.String && int.TryParse(value.GetString(), out var parsed))
        {
            return parsed;
        }
        throw new RuleException($"\"{name}\" must be an integer.");
    }

    private static T ReadEnum<T>(JsonElement obj, string name, T fallback, Func<string, T> parser)
    {
        if (!obj.TryGetProperty(name, out var value) || value.ValueKind == JsonValueKind.Null)
        {
            return fallback;
        }
        if (value.ValueKind != JsonValueKind.String)
        {
            throw new RuleException($"\"{name}\" must be a string.");
        }
        return parser(value.GetString() ?? string.Empty);
    }

    // ---- enum spellings ----------------------------------------------------

    private static ApplyTo ParseApplyTo(string raw) => raw.ToLowerInvariant() switch
    {
        "name" => ApplyTo.Name,
        "nameandextension" => ApplyTo.NameAndExtension,
        _ => throw new RuleException($"unknown applyTo value '{raw}'."),
    };

    private static SortMode ParseSort(string raw) => raw.ToLowerInvariant() switch
    {
        "name" => SortMode.Name,
        "created" => SortMode.Created,
        "modified" => SortMode.Modified,
        _ => throw new RuleException($"unknown sort value '{raw}'."),
    };

    private static StepKind ParseOp(string raw, int index) => raw.ToLowerInvariant() switch
    {
        "replace" => StepKind.Replace,
        "insert" => StepKind.Insert,
        "remove" => StepKind.Remove,
        "sequence" => StepKind.Sequence,
        "case" => StepKind.Case,
        "extension" => StepKind.Extension,
        _ => throw new RuleException($"steps[{index}] has unknown op '{raw}'."),
    };

    private static Position ParsePosition(string raw) => raw.ToLowerInvariant() switch
    {
        "prefix" => Position.Prefix,
        "suffix" => Position.Suffix,
        "index" => Position.Index,
        _ => throw new RuleException($"unknown position value '{raw}'."),
    };

    private static CaseMode ParseCaseMode(string raw) => raw.ToLowerInvariant() switch
    {
        "upper" => CaseMode.Upper,
        "lower" => CaseMode.Lower,
        "title" => CaseMode.Title,
        _ => throw new RuleException($"unknown case mode '{raw}'."),
    };

    private static ExtensionMode ParseExtensionMode(string raw) => raw.ToLowerInvariant() switch
    {
        "lower" => ExtensionMode.Lower,
        "upper" => ExtensionMode.Upper,
        "set" => ExtensionMode.Set,
        _ => throw new RuleException($"unknown extension mode '{raw}'."),
    };
}

