    }

    private static T ReadEnum<T>(JsonElement obj, string name, T fallback, Func<string, T> parser)
    {
        if (!obj.TryGetProperty(name, out var value) || value.ValueKind == JsonValueKind.Null)
        {
            return fallback;
        }
        if (value.ValueKind != JsonValueKind.String)
        {
            throw new RuleException($"\"{name}\" must be a string.");
        }
        return parser(value.GetString() ?? string.Empty);
    }

    // ---- enum spellings ----------------------------------------------------

    private static ApplyTo ParseApplyTo(string raw) => raw.ToLowerInvariant() switch
    {
        "name" => ApplyTo.Name,
        "nameandextension" => ApplyTo.NameAndExtension,
        _ => throw new RuleException($"unknown applyTo value '{raw}'."),
    };

    private static SortMode ParseSort(string raw) => raw.ToLowerInvariant() switch
    {
        "name" => SortMode.Name,
        "created" => SortMode.Created,
        "modified" => SortMode.Modified,
        _ => throw new RuleException($"unknown sort value '{raw}'."),
    };

    private static StepKind ParseOp(string raw, int index) => raw.ToLowerInvariant() switch
    {
        "replace" => StepKind.Replace,
        "insert" => StepKind.Insert,
        "remove" => StepKind.Remove,
        "sequence" => StepKind.Sequence,
        "case" => StepKind.Case,
        "extension" => StepKind.Extension,
        _ => throw new RuleException($"steps[{index}] has unknown op '{raw}'."),
    };

    private static Position ParsePosition(string raw) => raw.ToLowerInvariant() switch
    {
        "prefix" => Position.Prefix,
        "suffix" => Position.Suffix,
        "index" => Position.Index,
        _ => throw new RuleException($"unknown position value '{raw}'."),
    };

    private static CaseMode ParseCaseMode(string raw) => raw.ToLowerInvariant() switch
    {
        "upper" => CaseMode.Upper,
        "lower" => CaseMode.Lower,
        "title" => CaseMode.Title,
        _ => throw new RuleException($"unknown case mode '{raw}'."),
    };

    private static ExtensionMode ParseExtensionMode(string raw) => raw.ToLowerInvariant() switch
    {
        "lower" => ExtensionMode.Lower,
        "upper" => ExtensionMode.Upper,
        "set" => ExtensionMode.Set,
        _ => throw new RuleException($"unknown extension mode '{raw}'."),
    };
}

