namespace BatchRenameStudio.Core;

/// <summary>
/// The literal name-level rules from the contract: how a file name splits into base + extension,
/// how it is put back together, and what makes a proposed name invalid on Windows.
/// </summary>
public static class NameRules
{
    public const int MaxNameLength = 255;

    private static readonly char[] ForbiddenChars = { '<', '>', ':', '"', '/', '\\', '|', '?', '*' };

    private static readonly HashSet<string> ReservedDeviceNames = BuildReservedNames();

    /// <summary>
    /// Splits on the LAST '.' in the name. The dot must not be at index 0, so ".gitignore"
    /// keeps its whole name as the base and has no extension. The extension excludes the dot.
    /// </summary>
    public static (string Base, string Ext) Split(string name)
    {
        int dot = name.LastIndexOf('.');
        if (dot > 0)
        {
            return (name.Substring(0, dot), name.Substring(dot + 1));
        }
        return (name, string.Empty);
    }

    /// <summary>Inverse of <see cref="Split"/>: the dot only reappears when the extension is non-empty.</summary>
    public static string Join(string baseName, string ext)
        => ext.Length > 0 ? baseName + "." + ext : baseName;

    /// <summary>True when the proposed name cannot exist as a file name on Windows.</summary>
    public static bool IsInvalid(string proposed, out string reason)
    {
        if (proposed.Length == 0)
        {
            reason = "proposed name is empty";
            return true;
        }

        if (proposed.Length > MaxNameLength)
        {
            reason = $"proposed name is longer than {MaxNameLength} characters";
            return true;
        }

        foreach (char c in proposed)
        {
            if (c < ' ')
            {
                reason = "proposed name contains a control character";
                return true;
            }
            if (Array.IndexOf(ForbiddenChars, c) >= 0)
            {
                reason = $"proposed name contains the forbidden character '{c}'";
                return true;
            }
        }

        var (baseName, _) = Split(proposed);
        if (ReservedDeviceNames.Contains(baseName))
        {
            reason = $"'{baseName}' is a reserved Windows device name";
            return true;
        }

        reason = string.Empty;
        return false;
    }

    private static HashSet<string> BuildReservedNames()
    {
        var set = new HashSet<string>(StringComparer.OrdinalIgnoreCase)
        {
            "CON", "PRN", "AUX", "NUL",
        };
        for (int i = 1; i <= 9; i++)
        {
            set.Add("COM" + i);
            set.Add("LPT" + i);
        }
        return set;
    }
}

