namespace BatchRenameStudio.Core;

public enum PlanStatus
{
    Ok,
    Collision,
    Unchanged,
    Invalid,
}

/// <summary>One directory entry, decoupled from the filesystem so the planner stays testable.</summary>
public sealed class FileEntry
{
    public required string Name { get; init; }
    public DateTime CreatedUtc { get; init; }
    public DateTime ModifiedUtc { get; init; }
    public long Length { get; init; }

    public static FileEntry FromInfo(FileInfo info) => new()
    {
        Name = info.Name,
        CreatedUtc = info.CreationTimeUtc,
        ModifiedUtc = info.LastWriteTimeUtc,
        Length = SafeLength(info),
    };

    private static long SafeLength(FileInfo info)
    {
        try
        {
            return info.Length;
        }
        catch (IOException)
        {
            return 0;
        }
    }
}

public sealed class PlanItem
{
    public required string Original { get; init; }
    public required string Proposed { get; set; }
    public PlanStatus Status { get; set; }
    public string Reason { get; set; } = string.Empty;

    public string StatusText => Status switch
    {
        PlanStatus.Ok => "ok",
        PlanStatus.Collision => "collision",
        PlanStatus.Unchanged => "unchanged",
        _ => "invalid",
    };
}

public sealed class PlanSummary
{
    public int Total { get; set; }
    public int Ok { get; set; }
    public int Collision { get; set; }
    public int Unchanged { get; set; }
    public int Invalid { get; set; }

    public override string ToString()
        => $"total={Total} ok={Ok} collision={Collision} unchanged={Unchanged} invalid={Invalid}";
}

public sealed class RenamePlan
{
    public const int SchemaVersion = 1;

    public List<PlanItem> Items { get; } = new();
    public PlanSummary Summary { get; } = new();
}

