    /// Processing order: the contract's sort, with an ordinal name tie-break so that equal
    /// timestamps can never make the output order depend on the filesystem's enumeration order.
    /// </summary>
    public static List<FileEntry> SortForProcessing(IEnumerable<FileEntry> files, SortMode sort)
    {
        var list = files.ToList();
        switch (sort)
        {
            case SortMode.Created:
                list.Sort((a, b) =>
                {
                    int c = a.CreatedUtc.CompareTo(b.CreatedUtc);
                    return c != 0 ? c : string.CompareOrdinal(a.Name, b.Name);
                });
                break;

            case SortMode.Modified:
                list.Sort((a, b) =>
                {
                    int c = a.ModifiedUtc.CompareTo(b.ModifiedUtc);
                    return c != 0 ? c : string.CompareOrdinal(a.Name, b.Name);
                });
                break;

            default:
                list.Sort((a, b) => string.CompareOrdinal(a.Name, b.Name));
                break;
        }
        return list;
    }

    public static RenamePlan Build(IEnumerable<FileEntry> files, RuleSet rules)
        => Build(files, StepEngine.Compile(rules));

    public static RenamePlan Build(IEnumerable<FileEntry> files, CompiledRules rules)
    {
        var ordered = SortForProcessing(files, rules.Sort);
        var plan = new RenamePlan();

        // Pass 1 - propose. The sequence counter advances for every file regardless of the
        // status that file ends up with, so it is simply the loop index.
        for (int i = 0; i < ordered.Count; i++)
        {
            string original = ordered[i].Name;
            plan.Items.Add(new PlanItem
            {
                Original = original,
                Proposed = StepEngine.Apply(rules, original, i),
            });
        }

        // Pass 2 - classify. Precedence: invalid > collision > unchanged > ok.
        var existingNames = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        foreach (var entry in ordered)
        {
