                    ? "target name is already taken by another file in the folder"
                    : "two or more files would end up with the same name";
                continue;
            }

            if (string.Equals(item.Proposed, item.Original, StringComparison.Ordinal))
            {
                item.Status = PlanStatus.Unchanged;
                item.Reason = string.Empty;
                continue;
            }

            item.Status = PlanStatus.Ok;
            item.Reason = string.Empty;
        }

        foreach (var item in plan.Items)
        {
            plan.Summary.Total++;
            switch (item.Status)
            {
                case PlanStatus.Ok: plan.Summary.Ok++; break;
                case PlanStatus.Collision: plan.Summary.Collision++; break;
                case PlanStatus.Unchanged: plan.Summary.Unchanged++; break;
                default: plan.Summary.Invalid++; break;
            }
        }

        return plan;
    }
}

