using System.Text;
using System.Text.Encodings.Web;
using System.Text.Json;

namespace BatchRenameStudio.Core;

/// <summary>
/// Writes plan.json. The output is deterministic: fixed property order, fixed indentation,
/// LF line endings on every platform, UTF-8 with no byte order mark.
/// </summary>
public static class PlanSerializer
{
    private static readonly JsonWriterOptions Options = new()
    {
        Indented = true,
        Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping,
    };

    public static string Serialize(RenamePlan plan)
    {
        using var stream = new MemoryStream();
        using (var writer = new Utf8JsonWriter(stream, Options))
        {
            writer.WriteStartObject();
            writer.WriteNumber("schemaVersion", RenamePlan.SchemaVersion);

            writer.WriteStartArray("items");
            foreach (var item in plan.Items)
            {
                writer.WriteStartObject();
                writer.WriteString("original", item.Original);
                writer.WriteString("proposed", item.Proposed);
                writer.WriteString("status", item.StatusText);
                writer.WriteString("reason", item.Reason);
                writer.WriteEndObject();
            }
            writer.WriteEndArray();

            writer.WriteStartObject("summary");
            writer.WriteNumber("total", plan.Summary.Total);
            writer.WriteNumber("ok", plan.Summary.Ok);
            writer.WriteNumber("collision", plan.Summary.Collision);
            writer.WriteNumber("unchanged", plan.Summary.Unchanged);
            writer.WriteNumber("invalid", plan.Summary.Invalid);
            writer.WriteEndObject();

            writer.WriteEndObject();
        }

        // Utf8JsonWriter indents with Environment.NewLine on .NET 8; normalise so the bytes are
        // identical no matter where the tool runs. File names cannot contain a raw CR or LF
        // (they are rejected as invalid), and JSON escapes any control character it does see,
        // so this only ever touches indentation.
        string json = Encoding.UTF8.GetString(stream.ToArray()).Replace("\r\n", "\n");
        return json + "\n";
    }

    /// <summary>Writes plan.json as UTF-8 without a BOM.</summary>
    public static void WriteFile(RenamePlan plan, string path)
    {
        string full = Path.GetFullPath(path);
        string? parent = Path.GetDirectoryName(full);
        if (!string.IsNullOrEmpty(parent) && !Directory.Exists(parent))
        {
            Directory.CreateDirectory(parent);
        }

        // Encoding.UTF8.GetBytes never emits a preamble, unlike a StreamWriter created with it.
        File.WriteAllBytes(full, Encoding.UTF8.GetBytes(Serialize(plan)));
    }
}

