using System.Globalization;
using System.Text;
using System.Text.Encodings.Web;
using System.Text.Json;

namespace BatchRenameStudio.Core;

public sealed class RenameOperation
{
    public required string From { get; init; }
    public required string To { get; init; }
}

/// <summary>
/// A record of one completed apply, in execution order. Undo replays it backwards.
/// Persisted next to the user's local app data so an undo survives closing the app.
/// </summary>
public sealed class RenameJournal
{
    public required string Folder { get; init; }
    public required string TimestampUtc { get; init; }
    public List<RenameOperation> Operations { get; } = new();

    public string? SourcePath { get; set; }

    public string Describe()
        => $"{Operations.Count} file(s) in {Folder} at {TimestampUtc}";
}

public sealed class RenameResult
{
    public int Renamed { get; set; }
    public List<string> Errors { get; } = new();
    public RenameJournal? Journal { get; set; }
    public bool RolledBack { get; set; }
    public bool Succeeded => Errors.Count == 0;
}

/// <summary>
/// Performs the actual renames. Every batch runs in two phases (everything to a unique
/// temporary name first, then to its final name) so that swaps and cycles - a.txt to b.txt
/// while b.txt goes to a.txt - and case-only renames all work without a special case.
/// A batch that fails part way is rolled back.
/// </summary>
public static class RenameExecutor
{
    private static readonly JsonWriterOptions JournalOptions = new()
    {
        Indented = true,
        Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping,
    };

    /// <summary>Renames every item whose status is <see cref="PlanStatus.Ok"/>.</summary>
    public static RenameResult Apply(string folder, IEnumerable<PlanItem> items)
    {
        var operations = items
            .Where(i => i.Status == PlanStatus.Ok)
            .Select(i => new RenameOperation { From = i.Original, To = i.Proposed })
            .ToList();

        return Execute(folder, operations);
    }

    /// <summary>Reverses a journal: every recorded target goes back to its original name.</summary>
    public static RenameResult Undo(RenameJournal journal)
    {
        var operations = journal.Operations
            .AsEnumerable()
            .Reverse()
            .Select(op => new RenameOperation { From = op.To, To = op.From })
            .ToList();

        return Execute(journal.Folder, operations);
    }

    private static RenameResult Execute(string folder, List<RenameOperation> operations)
    {
        var result = new RenameResult();
        if (operations.Count == 0)
        {
            return result;
        }

        if (!Directory.Exists(folder))
        {
            result.Errors.Add($"folder not found: {folder}");
            return result;
        }

        var staged = new List<(string TempPath, string FinalPath, RenameOperation Op)>();
        var completed = new List<(string From, string To)>();

        try
        {
            // Phase 1: source -> unique temporary name.
            foreach (var op in operations)
            {
                string source = Path.Combine(folder, op.From);
                string temp = Path.Combine(folder, MakeTempName());
                File.Move(source, temp);
                completed.Add((source, temp));
                staged.Add((temp, Path.Combine(folder, op.To), op));
            }

            // Phase 2: temporary -> final name.
            foreach (var (tempPath, finalPath, _) in staged)
            {
                File.Move(tempPath, finalPath);
                completed.Add((tempPath, finalPath));
                result.Renamed++;
            }
        }
        catch (Exception ex)
        {
            result.Errors.Add(ex.Message);
            result.Renamed = 0;
            RollBack(completed, result);
            result.RolledBack = true;
            return result;
        }

        var journal = new RenameJournal
        {
            Folder = folder,
            TimestampUtc = DateTime.UtcNow.ToString("yyyy-MM-dd'T'HH:mm:ss'Z'", CultureInfo.InvariantCulture),
        };
        journal.Operations.AddRange(operations);
        result.Journal = journal;

        try
        {
            journal.SourcePath = SaveJournal(journal);
        }
        catch (Exception ex)
        {
            // A journal we could not persist is not a reason to fail a rename that already
            // happened; the in-session undo stack still holds it.
            result.Errors.Add($"rename succeeded but the undo journal could not be saved: {ex.Message}");
        }

        return result;
    }

    private static void RollBack(List<(string From, string To)> completed, RenameResult result)
    {
        for (int i = completed.Count - 1; i >= 0; i--)
        {
            var (from, to) = completed[i];
            try
            {
                File.Move(to, from);
            }
            catch (Exception ex)
            {
                result.Errors.Add($"rollback failed for '{to}': {ex.Message}");
            }
        }
    }

    private static string MakeTempName()
        => "~brs-" + Guid.NewGuid().ToString("N") + ".tmp";

    public static string JournalDirectory
        => Path.Combine(
            Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
            "BatchRenameStudio",
            "journals");

    private static string SaveJournal(RenameJournal journal)
    {
        Directory.CreateDirectory(JournalDirectory);
        string name = "rename-"
                      + DateTime.UtcNow.ToString("yyyyMMdd-HHmmss-fff", CultureInfo.InvariantCulture)
                      + ".json";
        string path = Path.Combine(JournalDirectory, name);
        File.WriteAllBytes(path, Encoding.UTF8.GetBytes(SerializeJournal(journal)));
        return path;
    }

    public static string SerializeJournal(RenameJournal journal)
    {
        using var stream = new MemoryStream();
        using (var writer = new Utf8JsonWriter(stream, JournalOptions))
        {
            writer.WriteStartObject();
            writer.WriteNumber("schemaVersion", 1);
            writer.WriteString("folder", journal.Folder);
            writer.WriteString("timestampUtc", journal.TimestampUtc);
            writer.WriteStartArray("operations");
            foreach (var op in journal.Operations)
            {
                writer.WriteStartObject();
                writer.WriteString("from", op.From);
                writer.WriteString("to", op.To);
                writer.WriteEndObject();
            }
            writer.WriteEndArray();
            writer.WriteEndObject();
        }
        return Encoding.UTF8.GetString(stream.ToArray()).Replace("\r\n", "\n") + "\n";
    }

    public static RenameJournal LoadJournal(string path)
    {
        using var doc = JsonDocument.Parse(File.ReadAllText(path));
        var root = doc.RootElement;
        var journal = new RenameJournal
        {
            Folder = root.TryGetProperty("folder", out var f) ? f.GetString() ?? string.Empty : string.Empty,
            TimestampUtc = root.TryGetProperty("timestampUtc", out var t) ? t.GetString() ?? string.Empty : string.Empty,
            SourcePath = path,
        };

        if (root.TryGetProperty("operations", out var ops) && ops.ValueKind == JsonValueKind.Array)
        {
            foreach (var op in ops.EnumerateArray())
            {
                journal.Operations.Add(new RenameOperation
                {
                    From = op.TryGetProperty("from", out var from) ? from.GetString() ?? string.Empty : string.Empty,
                    To = op.TryGetProperty("to", out var to) ? to.GetString() ?? string.Empty : string.Empty,
                });
            }
        }

        return journal;
    }
}

