        => "~brs-" + Guid.NewGuid().ToString("N") + ".tmp";

    public static string JournalDirectory
        => Path.Combine(
            Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
            "BatchRenameStudio",
            "journals");

    private static string SaveJournal(RenameJournal journal)
    {
        Directory.CreateDirectory(JournalDirectory);
        string name = "rename-"
                      + DateTime.UtcNow.ToString("yyyyMMdd-HHmmss-fff", CultureInfo.InvariantCulture)
                      + ".json";
        string path = Path.Combine(JournalDirectory, name);
        File.WriteAllBytes(path, Encoding.UTF8.GetBytes(SerializeJournal(journal)));
        return path;
    }

    public static string SerializeJournal(RenameJournal journal)
    {
        using var stream = new MemoryStream();
        using (var writer = new Utf8JsonWriter(stream, JournalOptions))
        {
            writer.WriteStartObject();
            writer.WriteNumber("schemaVersion", 1);
            writer.WriteString("folder", journal.Folder);
            writer.WriteString("timestampUtc", journal.TimestampUtc);
            writer.WriteStartArray("operations");
            foreach (var op in journal.Operations)
            {
                writer.WriteStartObject();
                writer.WriteString("from", op.From);
                writer.WriteString("to", op.To);
                writer.WriteEndObject();
            }
            writer.WriteEndArray();
            writer.WriteEndObject();
        }
        return Encoding.UTF8.GetString(stream.ToArray()).Replace("\r\n", "\n") + "\n";
    }

    public static RenameJournal LoadJournal(string path)
    {
        using var doc = JsonDocument.Parse(File.ReadAllText(path));
        var root = doc.RootElement;
        var journal = new RenameJournal
        {
            Folder = root.TryGetProperty("folder", out var f) ? f.GetString() ?? string.Empty : string.Empty,
            TimestampUtc = root.TryGetProperty("timestampUtc", out var t) ? t.GetString() ?? string.Empty : string.Empty,
            SourcePath = path,
        };

        if (root.TryGetProperty("operations", out var ops) && ops.ValueKind == JsonValueKind.Array)
        {
            foreach (var op in ops.EnumerateArray())
            {
                journal.Operations.Add(new RenameOperation
                {
                    From = op.TryGetProperty("from", out var from) ? from.GetString() ?? string.Empty : string.Empty,
                    To = op.TryGetProperty("to", out var to) ? to.GetString() ?? string.Empty : string.Empty,
                });
            }
        }

        return journal;
    }
}

