using BatchRenameStudio.Core;

namespace BatchRenameStudio.Cli;

/// <summary>
/// The headless half of the tool. Exit code 0 means success; 2 means the run was rejected
/// (bad arguments, missing folder, malformed rules, unwritable output).
/// </summary>
internal static class HeadlessRunner
{
    public const int ExitSuccess = 0;
    public const int ExitFailure = 2;

    public static int RunPlan(CliOptions options)
    {
        try
        {
            string directory = ResolveDirectory(options.Directory!);
            var rules = LoadRules(options.RulesPath!);
            var files = RenamePlanner.ListFiles(directory);
            var plan = RenamePlanner.Build(files, rules);

            // --plan never touches the folder; the only side effect is the output file.
            PlanSerializer.WriteFile(plan, options.OutPath!);

            Console.Out.WriteLine(plan.Summary.ToString());
            return ExitSuccess;
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine("error: " + ex.Message);
            return ExitFailure;
        }
    }

    public static int RunApply(CliOptions options)
    {
        try
        {
            string directory = ResolveDirectory(options.Directory!);
            var rules = LoadRules(options.RulesPath!);
            var files = RenamePlanner.ListFiles(directory);
            var plan = RenamePlanner.Build(files, rules);

            if (!string.IsNullOrWhiteSpace(options.OutPath))
            {
                PlanSerializer.WriteFile(plan, options.OutPath);
            }

            var result = RenameExecutor.Apply(directory, plan.Items);
            if (!result.Succeeded)
            {
                foreach (string error in result.Errors)
                {
                    Console.Error.WriteLine("error: " + error);
                }
                if (result.Renamed == 0)
                {
                    return ExitFailure;
                }
            }

            Console.Out.WriteLine($"renamed={result.Renamed} {plan.Summary}");
            return ExitSuccess;
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine("error: " + ex.Message);
            return ExitFailure;
        }
    }

    private static string ResolveDirectory(string raw)
    {
        string full = Path.GetFullPath(raw);
        if (!Directory.Exists(full))
        {
            throw new DirectoryNotFoundException($"folder not found: {full}");
        }
        return full;
    }

    private static RuleSet LoadRules(string raw)
    {
        string full = Path.GetFullPath(raw);
        if (!File.Exists(full))
        {
            throw new FileNotFoundException($"rules file not found: {full}");
        }
        return RuleSetSerializer.ParseFile(full);
    }
}

