using System.Text.RegularExpressions;

namespace BatchRenameStudio.Core;

/// <summary>A rule step with its per-run precomputed state (regex, sequence token layout).</summary>
public sealed class CompiledStep
{
    public required RuleStep Step { get; init; }

    /// <summary>Non-null only for a regex replace step.</summary>
    public Regex? Pattern { get; init; }

    // Sequence layout: Literal before the {n:PAD} token, the pad width, and the literal after it.
    public string SequenceHead { get; init; } = string.Empty;
    public string SequenceTail { get; init; } = string.Empty;
    public int SequenceWidth { get; init; }
    public bool SequenceHasToken { get; init; }
}

/// <summary>A rule set compiled once and then applied to every file.</summary>
public sealed class CompiledRules
{
    public required ApplyTo ApplyTo { get; init; }
    public required SortMode Sort { get; init; }
    public required IReadOnlyList<CompiledStep> Steps { get; init; }
}

/// <summary>
/// Pure string transformations. Everything here is deterministic and has no filesystem
/// dependency, which is what makes the plan reproducible byte for byte.
/// </summary>
public static class StepEngine
{
    private static readonly TimeSpan RegexTimeout = TimeSpan.FromSeconds(2);

    private static readonly Regex SequenceToken =
        new(@"\{n:(0+)\}", RegexOptions.CultureInvariant, TimeSpan.FromSeconds(1));

    public static CompiledRules Compile(RuleSet rules)
    {
        var steps = new List<CompiledStep>(rules.Steps.Count);
        foreach (var step in rules.Steps)
        {
            if (!step.Enabled)
            {
                continue;
            }
            steps.Add(CompileStep(step));
        }

        return new CompiledRules
        {
            ApplyTo = rules.ApplyTo,
            Sort = rules.Sort,
            Steps = steps,
        };
    }

    private static CompiledStep CompileStep(RuleStep step)
    {
        Regex? pattern = null;
        if (step.Op == StepKind.Replace && step.Regex)
        {
            var options = RegexOptions.CultureInvariant;
            if (step.IgnoreCase)
            {
                options |= RegexOptions.IgnoreCase;
            }
            try
            {
                pattern = new Regex(step.Find, options, RegexTimeout);
            }
            catch (ArgumentException ex)
            {
                throw new RuleException($"invalid regular expression '{step.Find}': {ex.Message}", ex);
            }
        }

        string head = step.Pattern;
        string tail = string.Empty;
        int width = 0;
        bool hasToken = false;

        if (step.Op == StepKind.Sequence)
        {
            // Exactly one token is specified by the contract; if the author wrote more than one,
            // only the first is substituted and the rest stay literal.
            var match = SequenceToken.Match(step.Pattern);
            if (match.Success)
            {
                hasToken = true;
                head = step.Pattern.Substring(0, match.Index);
                tail = step.Pattern.Substring(match.Index + match.Length);
                width = match.Groups[1].Value.Length;
            }
        }

        return new CompiledStep
        {
            Step = step,
            Pattern = pattern,
            SequenceHead = head,
            SequenceTail = tail,
            SequenceWidth = width,
            SequenceHasToken = hasToken,
        };
    }

    /// <summary>
    /// Runs the whole compiled rule set against one file name and returns the proposed name.
    /// <paramref name="ordinal"/> is the 0-based StepPosition of the file in processing order and
    /// drives the sequence counter.
    /// </summary>
    public static string Apply(CompiledRules rules, string fileName, int ordinal)
    {
        bool whole = rules.ApplyTo == ApplyTo.NameAndExtension;
        var (baseName, ext) = NameRules.Split(fileName);
        string target = whole ? fileName : baseName;

        foreach (var compiled in rules.Steps)
        {
            if (compiled.Step.Op == StepKind.Extension)
            {
                if (whole)
                {
                    // Rule 12: the extension op still acts on the trailing extension of the
                    // string produced so far.
                    var (innerBase, innerExt) = NameRules.Split(target);
                    target = NameRules.Join(innerBase, ApplyExtension(compiled.Step, innerExt));
                }
                else
                {
                    ext = ApplyExtension(compiled.Step, ext);
                }
                continue;
            }

            target = ApplyToText(compiled, target, ordinal);
        }

        return whole ? target : NameRules.Join(target, ext);
    }

    private static string ApplyToText(CompiledStep compiled, string text, int ordinal)
    {
        var step = compiled.Step;
        return step.Op switch
        {
            StepKind.Replace => ApplyReplace(compiled, text),
            StepKind.Insert => ApplyInsert(step, text),
            StepKind.Remove => ApplyRemove(step, text),
            StepKind.Sequence => ApplySequence(compiled, text, ordinal),
            StepKind.Case => ApplyCase(step.CaseMode, text),
            _ => text,
        };
    }

    public static string ApplyReplace(CompiledStep compiled, string text)
    {
        var step = compiled.Step;
        if (compiled.Pattern is not null)
        {
            return compiled.Pattern.Replace(text, step.ReplaceWith);
        }

        if (step.Find.Length == 0)
        {
            // string.Replace rejects an empty needle; treat it as a no-op instead of failing.
            return text;
        }

        var comparison = step.IgnoreCase ? StringComparison.OrdinalIgnoreCase : StringComparison.Ordinal;
        return text.Replace(step.Find, step.ReplaceWith, comparison);
    }

    public static string ApplyInsert(RuleStep step, string text)
    {
        switch (step.Position)
        {
            case StepPosition.Prefix:
                return step.Text + text;
            case StepPosition.Suffix:
                return text + step.Text;
            default:
                int at = Math.Clamp(step.Index, 0, text.Length);
                return text.Insert(at, step.Text);
        }
    }

    public static string ApplyRemove(RuleStep step, string text)
    {
        int from = Math.Clamp(step.From, 0, text.Length);
        int remaining = text.Length - from;
        int count = Math.Clamp(step.Count, 0, remaining);
        return count == 0 ? text : text.Remove(from, count);
    }

    public static string ApplySequence(CompiledStep compiled, string text, int ordinal)
    {
        var step = compiled.Step;
        long number = (long)step.Start + (long)step.Step * ordinal;
        string rendered = compiled.SequenceHasToken
            ? compiled.SequenceHead
              + number.ToString(new string('0', compiled.SequenceWidth), CultureInfo.InvariantCulture)
              + compiled.SequenceTail
            : compiled.SequenceHead;

        return step.Position == StepPosition.Suffix ? text + rendered : rendered + text;
    }

    public static string ApplyCase(CaseMode mode, string text)
    {
        switch (mode)
        {
            case CaseMode.Upper:
                return text.ToUpperInvariant();
            case CaseMode.Lower:
                return text.ToLowerInvariant();
            default:
                return ToTitleCase(text);
        }
    }

    /// <summary>
    /// For every maximal run of Unicode letters: first character upper, the rest lower.
    /// Non-letters pass through untouched and end the current run.
    /// </summary>
    public static string ToTitleCase(string text)
    {
        var builder = new StringBuilder(text.Length);
        bool atRunStart = true;
        foreach (char c in text)
        {
            if (char.IsLetter(c))
            {
                builder.Append(atRunStart ? char.ToUpperInvariant(c) : char.ToLowerInvariant(c));
                atRunStart = false;
            }
            else
            {
                builder.Append(c);
                atRunStart = true;
            }
        }
        return builder.ToString();
    }

    public static string ApplyExtension(RuleStep step, string ext) => step.ExtensionMode switch
    {
        ExtensionMode.Lower => ext.ToLowerInvariant(),
        ExtensionMode.Upper => ext.ToUpperInvariant(),
        _ => step.Value,
    };
}

