using BatchRenameStudio.Core;

namespace BatchRenameStudio.Ui;

/// <summary>
/// Editor for whichever rule step is selected. The control tree is rebuilt from scratch every
/// time the selection changes, so each op only ever shows the fields that belong to it - no
/// greyed-out clutter and no stale event handlers.
/// </summary>
internal sealed class StepEditorPanel : Panel
{
    private static readonly string[] InsertPositions = { "prefix", "suffix", "index" };
    private static readonly string[] SequencePositions = { "prefix", "suffix" };
    private static readonly string[] CaseModes = { "upper", "lower", "title" };
    private static readonly string[] ExtensionModes = { "lower", "upper", "set" };

    private readonly Action _changed;
    private TableLayoutPanel? _table;
    private RuleStep? _step;

    public StepEditorPanel(Action changed)
    {
        _changed = changed;
        AutoScroll = true;
        Padding = new Padding(8, 6, 8, 6);
    }

    public void Bind(RuleStep? step)
    {
        _step = step;
        Rebuild();
    }

    /// <summary>Re-renders the current step, e.g. after an undo of an external edit.</summary>
    public void Reload() => Rebuild();

    private void Rebuild()
    {
        SuspendLayout();
        foreach (Control control in Controls.Cast<Control>().ToArray())
        {
            Controls.Remove(control);
            control.Dispose();
        }

        if (_step is null)
        {
            var hint = new Label
            {
                Text = "Select a step on the left, or use Add to create one.",
                Dock = DockStyle.Top,
                AutoSize = true,
                ForeColor = SystemColors.GrayText,
            };
            Controls.Add(hint);
            ResumeLayout();
            return;
        }

        _table = new TableLayoutPanel
        {
            Dock = DockStyle.Top,
            ColumnCount = 2,
            AutoSize = true,
            AutoSizeMode = AutoSizeMode.GrowAndShrink,
        };
        _table.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute, 110));
        _table.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 100));

        switch (_step.Op)
        {
            case StepKind.Replace: BuildReplace(_step); break;
            case StepKind.Insert: BuildInsert(_step); break;
            case StepKind.Remove: BuildRemove(_step); break;
            case StepKind.Sequence: BuildSequence(_step); break;
            case StepKind.Case: BuildCase(_step); break;
            case StepKind.Extension: BuildExtension(_step); break;
        }

        Controls.Add(_table);
        ResumeLayout(true);
    }

    // ---- per-op field sets -------------------------------------------------

    private void BuildReplace(RuleStep step)
    {
        AddText("Find", step.Find, v => step.Find = v);
        AddText("Replace with", step.ReplaceWith, v => step.ReplaceWith = v);
        AddCheck("Regular expression ($1 back-references allowed)", step.Regex, v => step.Regex = v);
        AddCheck("Ignore case", step.IgnoreCase, v => step.IgnoreCase = v);
        AddHint("Every occurrence is replaced.");
    }

    private void BuildInsert(RuleStep step)
    {
        AddText("Text", step.Text, v => step.Text = v);
        var index = MakeNumeric(step.Index, v => step.Index = v);
        AddCombo("Position", InsertPositions, (int)step.Position, v =>
        {
            step.Position = (StepPosition)v;
            index.Enabled = step.Position == StepPosition.Index;
        });
        AddRow("Index", index);
        index.Enabled = step.Position == StepPosition.Index;
        AddHint("Index is 0-based and clamped to the length of the target text.");
    }

    private void BuildRemove(RuleStep step)
    {
        AddRow("From", MakeNumeric(step.From, v => step.From = v));
        AddRow("Count", MakeNumeric(step.Count, v => step.Count = v));
        AddHint("Both values are clamped, so an over-long range simply removes what is left.");
    }

    private void BuildSequence(RuleStep step)
    {
        AddText("Pattern", step.Pattern, v => step.Pattern = v);
        AddRow("Start", MakeNumeric(step.Start, v => step.Start = v));
        AddRow("Step", MakeNumeric(step.Step, v => step.Step = v));
        int selected = step.Position == StepPosition.Suffix ? 1 : 0;
        AddCombo("Position", SequencePositions, selected,
            v => step.Position = v == 1 ? StepPosition.Suffix : StepPosition.Prefix);
        AddHint("Use one {n:000} token; the zeroes set the padding width. The counter advances\n"
                + "for every file in processing order, including skipped ones.");
    }

    private void BuildCase(RuleStep step)
    {
        AddCombo("Mode", CaseModes, (int)step.CaseMode, v => step.CaseMode = (CaseMode)v);
        AddHint("Title case capitalises the first letter of each run of letters.");
    }

    private void BuildExtension(RuleStep step)
    {
        var value = MakeText(step.Value, v => step.Value = v);
        AddCombo("Mode", ExtensionModes, (int)step.ExtensionMode, v =>
        {
            step.ExtensionMode = (ExtensionMode)v;
            value.Enabled = step.ExtensionMode == ExtensionMode.Set;
        });
        AddRow("Value", value);
        value.Enabled = step.ExtensionMode == ExtensionMode.Set;
        AddHint("Always acts on the extension, whatever \"Apply to\" is set to. No leading dot.");
    }

    // ---- row helpers -------------------------------------------------------

    private void AddRow(string label, Control control)
    {
        var caption = new Label
        {
            Text = label,
            Dock = DockStyle.Fill,
            TextAlign = ContentAlignment.MiddleLeft,
            Margin = new Padding(0, 4, 6, 0),
        };
        control.Margin = new Padding(0, 3, 4, 3);
        _table!.Controls.Add(caption);
        _table.Controls.Add(control);
    }

    private void AddText(string label, string value, Action<string> setter)
        => AddRow(label, MakeText(value, setter));

    private TextBox MakeText(string value, Action<string> setter)
    {
        var box = new TextBox { Text = value, Dock = DockStyle.Fill, Width = 240 };
        box.TextChanged += (_, _) =>
        {
            setter(box.Text);
            _changed();
        };
        return box;
    }

    private NumericUpDown MakeNumeric(int value, Action<int> setter)
    {
        var spin = new NumericUpDown
        {
            Minimum = -1_000_000,
            Maximum = 1_000_000,
            Value = Math.Clamp(value, -1_000_000, 1_000_000),
            Width = 100,
        };
        spin.ValueChanged += (_, _) =>
        {
            setter((int)spin.Value);
            _changed();
        };
        return spin;
    }

    private void AddCheck(string label, bool value, Action<bool> setter)
    {
        var box = new CheckBox
        {
            Text = label,
            Checked = value,
            AutoSize = true,
            Margin = new Padding(0, 4, 4, 0),
        };
        box.CheckedChanged += (_, _) =>
        {
            setter(box.Checked);
            _changed();
        };
        _table!.Controls.Add(new Label { Text = string.Empty, Margin = new Padding(0) });
        _table.Controls.Add(box);
    }

    private void AddCombo(string label, string[] items, int selected, Action<int> setter)
    {
        var combo = new ComboBox
        {
            DropDownStyle = ComboBoxStyle.DropDownList,
            Dock = DockStyle.Fill,
            Width = 160,
        };
        combo.Items.AddRange(items);
        combo.SelectedIndex = Math.Clamp(selected, 0, items.Length - 1);
        combo.SelectedIndexChanged += (_, _) =>
        {
            setter(combo.SelectedIndex);
            _changed();
        };
        AddRow(label, combo);
    }

    private void AddHint(string text)
    {
        var hint = new Label
        {
            Text = text,
            AutoSize = true,
            ForeColor = SystemColors.GrayText,
            Margin = new Padding(0, 8, 4, 0),
        };
        _table!.Controls.Add(new Label { Text = string.Empty, Margin = new Padding(0) });
        _table.Controls.Add(hint);
    }
}

