using BatchRenameStudio.Core;

namespace BatchRenameStudio.Ui;

/// <summary>
/// The whole GUI: pick a folder, stack up rule steps, watch the preview update as you type,
/// then apply. The preview is produced by the very same planner the headless --plan mode uses,
/// so what the grid shows is exactly what an apply will do.
/// </summary>
public sealed class MainForm : Form
{
    private static readonly Color OkColor = Color.FromArgb(232, 245, 233);
    private static readonly Color CollisionColor = Color.FromArgb(255, 226, 226);
    private static readonly Color InvalidColor = Color.FromArgb(255, 240, 214);
    private static readonly Color UnchangedColor = Color.FromArgb(246, 246, 246);

    private readonly RuleSet _rules = new();
    private readonly List<RenameJournal> _undoStack = new();
    private List<FileEntry> _files = new();
    private RenamePlan _plan = new();
    private string _folder = string.Empty;

    private readonly TextBox _folderBox = new();
    private readonly ComboBox _applyToCombo = new();
    private readonly ComboBox _sortCombo = new();
    private readonly ListView _stepList = new();
    private readonly StepEditorPanel _editor;
    private readonly DataGridView _grid = new();
    private readonly Label _summaryLabel = new();
    private readonly Button _applyButton = new();
    private readonly Button _undoButton = new();
    private readonly ToolStripStatusLabel _statusLabel = new();
    private readonly System.Windows.Forms.Timer _debounce = new();

    private bool _suspendListEvents;

    public MainForm(string? initialDirectory)
    {
        _editor = new StepEditorPanel(OnStepEdited);
        BuildUi();

        _debounce.Interval = 120;
        _debounce.Tick += (_, _) =>
        {
            _debounce.Stop();
            RefreshPreview();
        };

        if (!string.IsNullOrWhiteSpace(initialDirectory))
        {
            LoadFolder(initialDirectory!);
        }
        else
        {
            UpdateStatus("Choose a folder to begin.");
        }
    }

    // ---- construction ------------------------------------------------------

    private void BuildUi()
    {
        Text = "Batch Rename Studio";
        MinimumSize = new Size(940, 560);
        Size = new Size(1180, 720);
        StartPosition = FormStartPosition.CenterScreen;
        AllowDrop = true;
        DragEnter += OnDragEnter;
        DragDrop += OnDragDrop;

        var split = new SplitContainer
        {
            Dock = DockStyle.Fill,
            Orientation = Orientation.Vertical,
            SplitterWidth = 6,
        };
        split.Panel1.Controls.Add(BuildRulesPane());
        split.Panel2.Controls.Add(BuildPreviewPane());

        var status = new StatusStrip();
        _statusLabel.Spring = true;
        _statusLabel.TextAlign = ContentAlignment.MiddleLeft;
        status.Items.Add(_statusLabel);

        // Docked layout is resolved from the last added control backwards, so the Fill control
        // goes in first and the menu strip last.
        Controls.Add(split);
        Controls.Add(status);
        Controls.Add(BuildActionBar());
        Controls.Add(BuildFolderBar());
        Controls.Add(BuildMenu());

        // Set after the container is realised, otherwise the value is clamped away.
        Shown += (_, _) =>
        {
            split.SplitterDistance = 430;
            split.Panel1MinSize = 340;
            split.Panel2MinSize = 380;
        };
    }

    private MenuStrip BuildMenu()
    {
        var menu = new MenuStrip();

        var file = new ToolStripMenuItem("&File");
        file.DropDownItems.Add("&Open folder...", null, (_, _) => BrowseForFolder());
        file.DropDownItems.Add("&Reload folder", null, (_, _) => ReloadFolder());
        file.DropDownItems.Add(new ToolStripSeparator());
        file.DropDownItems.Add("&Load rules...", null, (_, _) => LoadRules());
        file.DropDownItems.Add("&Save rules...", null, (_, _) => SaveRules());
        file.DropDownItems.Add("&Export plan.json...", null, (_, _) => ExportPlan());
        file.DropDownItems.Add(new ToolStripSeparator());
        file.DropDownItems.Add("E&xit", null, (_, _) => Close());

        var rules = new ToolStripMenuItem("&Rules");
        var add = new ToolStripMenuItem("&Add step");
        foreach (StepKind kind in Enum.GetValues<StepKind>())
        {
            var captured = kind;
            add.DropDownItems.Add(kind.ToString().ToLowerInvariant(), null, (_, _) => AddStep(captured));
        }
        rules.DropDownItems.Add(add);
        rules.DropDownItems.Add("&Duplicate step", null, (_, _) => DuplicateStep());
        rules.DropDownItems.Add("&Remove step", null, (_, _) => RemoveStep());
        rules.DropDownItems.Add(new ToolStripSeparator());
        rules.DropDownItems.Add("Move &up", null, (_, _) => MoveStep(-1));
        rules.DropDownItems.Add("Move &down", null, (_, _) => MoveStep(1));
        rules.DropDownItems.Add(new ToolStripSeparator());
        rules.DropDownItems.Add("&Clear all steps", null, (_, _) => ClearSteps());

        var undo = new ToolStripMenuItem("&Undo");
        undo.DropDownItems.Add("Undo &last rename", null, (_, _) => UndoLast());
        undo.DropDownItems.Add("Undo from &journal file...", null, (_, _) => UndoFromFile());
        undo.DropDownItems.Add("Open journal &folder", null, (_, _) => OpenJournalFolder());

        var help = new ToolStripMenuItem("&Help");
        help.DropDownItems.Add("&About", null, (_, _) => ShowAbout());

        menu.Items.Add(file);
        menu.Items.Add(rules);
        menu.Items.Add(undo);
        menu.Items.Add(help);
        return menu;
    }

    private Control BuildFolderBar()
    {
        var bar = new Panel { Dock = DockStyle.Top, Height = 66, Padding = new Padding(8, 6, 8, 6) };

        var folderLabel = new Label { Text = "Folder", AutoSize = true, Location = new Point(8, 10) };
        _folderBox.Location = new Point(60, 6);
        _folderBox.Width = 620;
        _folderBox.Anchor = AnchorStyles.Top | AnchorStyles.Left | AnchorStyles.Right;
        _folderBox.KeyDown += (_, e) =>
        {
            if (e.KeyCode == Keys.Enter)
            {
                e.SuppressKeyPress = true;
                LoadFolder(_folderBox.Text);
            }
        };

        var browse = new Button { Text = "Browse...", Location = new Point(690, 4), Width = 90, Anchor = AnchorStyles.Top | AnchorStyles.Right };
        browse.Click += (_, _) => BrowseForFolder();

        var reload = new Button { Text = "Reload", Location = new Point(788, 4), Width = 80, Anchor = AnchorStyles.Top | AnchorStyles.Right };
        reload.Click += (_, _) => ReloadFolder();

        var applyToLabel = new Label { Text = "Apply to", AutoSize = true, Location = new Point(8, 40) };
        _applyToCombo.DropDownStyle = ComboBoxStyle.DropDownList;
        _applyToCombo.Items.AddRange(new object[] { "name", "nameAndExtension" });
        _applyToCombo.SelectedIndex = 0;
        _applyToCombo.Location = new Point(60, 36);
        _applyToCombo.Width = 160;
        _applyToCombo.SelectedIndexChanged += (_, _) =>
        {
            _rules.ApplyTo = _applyToCombo.SelectedIndex == 1 ? ApplyTo.NameAndExtension : ApplyTo.Name;
            RefreshPreview();
        };

        var sortLabel = new Label { Text = "Order by", AutoSize = true, Location = new Point(240, 40) };
        _sortCombo.DropDownStyle = ComboBoxStyle.DropDownList;
        _sortCombo.Items.AddRange(new object[] { "name", "created", "modified" });
        _sortCombo.SelectedIndex = 0;
        _sortCombo.Location = new Point(300, 36);
        _sortCombo.Width = 140;
        _sortCombo.SelectedIndexChanged += (_, _) =>
        {
            _rules.Sort = (SortMode)_sortCombo.SelectedIndex;
            RefreshPreview();
        };

        bar.Controls.Add(folderLabel);
        bar.Controls.Add(_folderBox);
        bar.Controls.Add(browse);
        bar.Controls.Add(reload);
        bar.Controls.Add(applyToLabel);
        bar.Controls.Add(_applyToCombo);
        bar.Controls.Add(sortLabel);
        bar.Controls.Add(_sortCombo);
        return bar;
    }

    private Control BuildRulesPane()
    {
        var layout = new TableLayoutPanel
        {
            Dock = DockStyle.Fill,
            ColumnCount = 1,
            RowCount = 3,
        };
        layout.RowStyles.Add(new RowStyle(SizeType.Absolute, 30));
        layout.RowStyles.Add(new RowStyle(SizeType.Percent, 100));
        layout.RowStyles.Add(new RowStyle(SizeType.Absolute, 250));

        var tools = new ToolStrip { Dock = DockStyle.Fill, GripStyle = ToolStripGripStyle.Hidden };
        var addButton = new ToolStripDropDownButton("Add step");
        foreach (StepKind kind in Enum.GetValues<StepKind>())
        {
            var captured = kind;
            addButton.DropDownItems.Add(kind.ToString().ToLowerInvariant(), null, (_, _) => AddStep(captured));
        }
        tools.Items.Add(addButton);
        tools.Items.Add(new ToolStripSeparator());
        tools.Items.Add(new ToolStripButton("Duplicate", null, (_, _) => DuplicateStep()));
        tools.Items.Add(new ToolStripButton("Remove", null, (_, _) => RemoveStep()));
        tools.Items.Add(new ToolStripSeparator());
        tools.Items.Add(new ToolStripButton("Up", null, (_, _) => MoveStep(-1)));
        tools.Items.Add(new ToolStripButton("Down", null, (_, _) => MoveStep(1)));

        _stepList.View = View.Details;
        _stepList.Dock = DockStyle.Fill;
        _stepList.CheckBoxes = true;
        _stepList.FullRowSelect = true;
        _stepList.MultiSelect = false;
        _stepList.HideSelection = false;
        _stepList.Columns.Add("#", 34);
        _stepList.Columns.Add("Step", 360);
        _stepList.SelectedIndexChanged += (_, _) => _editor.Bind(SelectedStep());
        _stepList.ItemChecked += (_, e) =>
        {
            if (_suspendListEvents)
            {
                return;
            }
            if (e.Item.Index >= 0 && e.Item.Index < _rules.Steps.Count)
            {
                _rules.Steps[e.Item.Index].Enabled = e.Item.Checked;
                RefreshPreview();
            }
        };

        var editorBox = new GroupBox { Text = "Step settings", Dock = DockStyle.Fill };
        _editor.Dock = DockStyle.Fill;
        editorBox.Controls.Add(_editor);
        _editor.Bind(null);

        layout.Controls.Add(tools, 0, 0);
        layout.Controls.Add(_stepList, 0, 1);
        layout.Controls.Add(editorBox, 0, 2);
        return layout;
    }

    private Control BuildPreviewPane()
    {
        var layout = new TableLayoutPanel
        {
            Dock = DockStyle.Fill,
            ColumnCount = 1,
            RowCount = 2,
        };
        layout.RowStyles.Add(new RowStyle(SizeType.Absolute, 28));
        layout.RowStyles.Add(new RowStyle(SizeType.Percent, 100));

        var legend = new FlowLayoutPanel { Dock = DockStyle.Fill, FlowDirection = FlowDirection.LeftToRight, Padding = new Padding(4, 4, 0, 0) };
        legend.Controls.Add(MakeSwatch("ok", OkColor));
        legend.Controls.Add(MakeSwatch("collision", CollisionColor));
        legend.Controls.Add(MakeSwatch("invalid", InvalidColor));
        legend.Controls.Add(MakeSwatch("unchanged", UnchangedColor));

        _grid.Dock = DockStyle.Fill;
        _grid.AllowUserToAddRows = false;
        _grid.AllowUserToDeleteRows = false;
        _grid.AllowUserToResizeRows = false;
        _grid.ReadOnly = true;
        _grid.RowHeadersVisible = false;
        _grid.SelectionMode = DataGridViewSelectionMode.FullRowSelect;
        _grid.AutoGenerateColumns = false;
        _grid.VirtualMode = true;
        _grid.EnableHeadersVisualStyles = false;
        _grid.ColumnHeadersHeightSizeMode = DataGridViewColumnHeadersHeightSizeMode.DisableResizing;

        AddColumn("Original", 30);
        AddColumn("Proposed", 30);
        AddColumn("Status", 12);
        AddColumn("Reason", 28);

        _grid.CellValueNeeded += (_, e) =>
        {
            if (e.RowIndex < 0 || e.RowIndex >= _plan.Items.Count)
            {
                return;
            }
            var item = _plan.Items[e.RowIndex];
            e.Value = e.ColumnIndex switch
            {
                0 => item.Original,
                1 => item.Proposed,
                2 => item.StatusText,
                _ => item.Reason,
            };
        };

        _grid.CellFormatting += (_, e) =>
        {
            if (e.RowIndex < 0 || e.RowIndex >= _plan.Items.Count)
            {
                return;
            }
            e.CellStyle.BackColor = _plan.Items[e.RowIndex].Status switch
            {
                PlanStatus.Ok => OkColor,
                PlanStatus.Collision => CollisionColor,
                PlanStatus.Invalid => InvalidColor,
                _ => UnchangedColor,
            };
        };

        layout.Controls.Add(legend, 0, 0);
        layout.Controls.Add(_grid, 0, 1);
        return layout;
    }

    private void AddColumn(string header, int weight)
    {
        _grid.Columns.Add(new DataGridViewTextBoxColumn
        {
            HeaderText = header,
            AutoSizeMode = DataGridViewAutoSizeColumnMode.Fill,
            FillWeight = weight,
            SortMode = DataGridViewColumnSortMode.NotSortable,
        });
    }

    private static Control MakeSwatch(string text, Color color)
    {
        return new Label
        {
            Text = "  " + text + "  ",
            BackColor = color,
            BorderStyle = BorderStyle.FixedSingle,
            AutoSize = true,
            Margin = new Padding(0, 0, 8, 0),
            TextAlign = ContentAlignment.MiddleCenter,
        };
    }

    private Control BuildActionBar()
    {
        var bar = new Panel { Dock = DockStyle.Bottom, Height = 46, Padding = new Padding(8, 6, 8, 6) };

        _summaryLabel.Text = "No folder loaded.";
        _summaryLabel.AutoSize = true;
        _summaryLabel.Location = new Point(10, 14);

        _undoButton.Text = "Undo last rename";
        _undoButton.Width = 150;
        _undoButton.Enabled = false;
        _undoButton.Anchor = AnchorStyles.Top | AnchorStyles.Right;
        _undoButton.Location = new Point(bar.Width - 320, 8);
        _undoButton.Click += (_, _) => UndoLast();

        _applyButton.Text = "Apply rename";
        _applyButton.Width = 150;
        _applyButton.Enabled = false;
        _applyButton.Anchor = AnchorStyles.Top | AnchorStyles.Right;
        _applyButton.Location = new Point(bar.Width - 160, 8);
        _applyButton.Click += (_, _) => ApplyRename();

        bar.Controls.Add(_summaryLabel);
        bar.Controls.Add(_undoButton);
        bar.Controls.Add(_applyButton);

        bar.Resize += (_, _) =>
        {
            _applyButton.Location = new Point(bar.Width - 168, 8);
            _undoButton.Location = new Point(bar.Width - 330, 8);
        };

        return bar;
    }

    // ---- folder handling ---------------------------------------------------

    private void BrowseForFolder()
    {
        using var dialog = new FolderBrowserDialog { Description = "Choose the folder to rename in", ShowNewFolderButton = false };
        if (!string.IsNullOrEmpty(_folder) && Directory.Exists(_folder))
        {
            dialog.SelectedPath = _folder;
        }
        if (dialog.ShowDialog(this) == DialogResult.OK)
        {
            LoadFolder(dialog.SelectedPath);
        }
    }

    private void LoadFolder(string folder)
    {
        try
        {
            string full = Path.GetFullPath(folder);
            if (!Directory.Exists(full))
            {
                MessageBox.Show(this, $"Folder not found:\n{full}", "Batch Rename Studio",
                    MessageBoxButtons.OK, MessageBoxIcon.Warning);
                return;
            }

            _folder = full;
            _folderBox.Text = full;
            _files = RenamePlanner.ListFiles(full);
            RefreshPreview();
        }
        catch (Exception ex)
        {
            MessageBox.Show(this, ex.Message, "Batch Rename Studio", MessageBoxButtons.OK, MessageBoxIcon.Error);
        }
    }

    private void ReloadFolder()
    {
        if (string.IsNullOrEmpty(_folder))
        {
            BrowseForFolder();
            return;
        }
        LoadFolder(_folder);
    }

    private void OnDragEnter(object? sender, DragEventArgs e)
    {
        if (e.Data?.GetDataPresent(DataFormats.FileDrop) == true)
        {
            e.Effect = DragDropEffects.Copy;
        }
    }

    private void OnDragDrop(object? sender, DragEventArgs e)
    {
        if (e.Data?.GetData(DataFormats.FileDrop) is not string[] paths || paths.Length == 0)
        {
            return;
        }
        string first = paths[0];
        LoadFolder(Directory.Exists(first) ? first : Path.GetDirectoryName(first) ?? first);
    }

    // ---- rule list ---------------------------------------------------------

    private RuleStep? SelectedStep()
    {
        int index = SelectedIndex();
        return index >= 0 ? _rules.Steps[index] : null;
    }

    private int SelectedIndex()
    {
        if (_stepList.SelectedIndices.Count == 0)
        {
            return -1;
        }
        int index = _stepList.SelectedIndices[0];
        return index >= 0 && index < _rules.Steps.Count ? index : -1;
    }

    private void AddStep(StepKind kind)
    {
        var step = new RuleStep { Op = kind };
        switch (kind)
        {
            case StepKind.Insert:
                step.Text = "new_";
                break;
            case StepKind.Remove:
                step.Count = 1;
                break;
            case StepKind.Extension:
                step.ExtensionMode = ExtensionMode.Lower;
                break;
        }

        _rules.Steps.Add(step);
        RebuildStepList(_rules.Steps.Count - 1);
        RefreshPreview();
    }

    private void DuplicateStep()
    {
        int index = SelectedIndex();
        if (index < 0)
        {
            return;
        }
        _rules.Steps.Insert(index + 1, _rules.Steps[index].Clone());
        RebuildStepList(index + 1);
        RefreshPreview();
    }

    private void RemoveStep()
    {
        int index = SelectedIndex();
        if (index < 0)
        {
            return;
        }
        _rules.Steps.RemoveAt(index);
        RebuildStepList(Math.Min(index, _rules.Steps.Count - 1));
        RefreshPreview();
    }

    private void MoveStep(int delta)
    {
        int index = SelectedIndex();
        int target = index + delta;
        if (index < 0 || target < 0 || target >= _rules.Steps.Count)
        {
            return;
        }
        (_rules.Steps[index], _rules.Steps[target]) = (_rules.Steps[target], _rules.Steps[index]);
        RebuildStepList(target);
        RefreshPreview();
    }

    private void ClearSteps()
    {
        if (_rules.Steps.Count == 0)
        {
            return;
        }
        if (MessageBox.Show(this, "Remove every step from the rule set?", "Batch Rename Studio",
                MessageBoxButtons.YesNo, MessageBoxIcon.Question) != DialogResult.Yes)
        {
            return;
        }
        _rules.Steps.Clear();
        RebuildStepList(-1);
        RefreshPreview();
    }

    private void RebuildStepList(int selectIndex)
    {
        _suspendListEvents = true;
        _stepList.BeginUpdate();
        _stepList.Items.Clear();
        for (int i = 0; i < _rules.Steps.Count; i++)
        {
            var step = _rules.Steps[i];
            var row = new ListViewItem((i + 1).ToString()) { Checked = step.Enabled };
            row.SubItems.Add(step.Describe());
            _stepList.Items.Add(row);
        }
        _stepList.EndUpdate();
        _suspendListEvents = false;

        if (selectIndex >= 0 && selectIndex < _stepList.Items.Count)
        {
            _stepList.Items[selectIndex].Selected = true;
            _stepList.Items[selectIndex].EnsureVisible();
            _stepList.Select();
        }
        _editor.Bind(SelectedStep());
    }

    private void OnStepEdited()
    {
        int index = SelectedIndex();
        if (index >= 0 && index < _stepList.Items.Count)
        {
            _stepList.Items[index].SubItems[1].Text = _rules.Steps[index].Describe();
        }
        _debounce.Stop();
        _debounce.Start();
    }

    // ---- preview -----------------------------------------------------------

    private void RefreshPreview()
    {
        if (string.IsNullOrEmpty(_folder))
        {
            _plan = new RenamePlan();
            BindGrid();
            _summaryLabel.Text = "No folder loaded.";
            _applyButton.Enabled = false;
            return;
        }

        try
        {
            _plan = RenamePlanner.Build(_files, _rules);
            BindGrid();
            _summaryLabel.Text = _plan.Summary.ToString();
            _applyButton.Enabled = _plan.Summary.Ok > 0;
            UpdateStatus($"{_folder}  -  {_files.Count} file(s)");
        }
        catch (RuleException ex)
        {
            _plan = new RenamePlan();
            BindGrid();
            _summaryLabel.Text = "Rule error";
            _applyButton.Enabled = false;
            UpdateStatus("Rule error: " + ex.Message);
        }
        catch (Exception ex)
        {
            _plan = new RenamePlan();
            BindGrid();
            _summaryLabel.Text = "Error";
            _applyButton.Enabled = false;
            UpdateStatus("Error: " + ex.Message);
        }
    }

    private void BindGrid()
    {
        _grid.RowCount = 0;
        _grid.RowCount = _plan.Items.Count;
        _grid.Invalidate();
    }

    private void UpdateStatus(string text) => _statusLabel.Text = text;

    // ---- apply and undo ----------------------------------------------------

    private void ApplyRename()
    {
        if (_plan.Summary.Ok == 0)
        {
            MessageBox.Show(this, "Nothing to rename: no item is marked \"ok\".", "Batch Rename Studio",
                MessageBoxButtons.OK, MessageBoxIcon.Information);
            return;
        }

        string message =
            $"Rename {_plan.Summary.Ok} file(s) in\n{_folder}\n\n"
            + $"Skipped: {_plan.Summary.Collision} collision, {_plan.Summary.Invalid} invalid, "
            + $"{_plan.Summary.Unchanged} unchanged.\n\nThis can be undone from the Undo menu.";

        if (MessageBox.Show(this, message, "Confirm rename", MessageBoxButtons.YesNo, MessageBoxIcon.Question)
            != DialogResult.Yes)
        {
            return;
        }

        RenameResult result;
        Cursor = Cursors.WaitCursor;
        try
        {
            result = RenameExecutor.Apply(_folder, _plan.Items);
        }
        finally
        {
            Cursor = Cursors.Default;
        }

        if (result.Journal is not null && result.Renamed > 0)
        {
            _undoStack.Add(result.Journal);
            _undoButton.Enabled = true;
        }

        ReportResult(result, result.Renamed + " file(s) renamed.");
        ReloadFolder();
    }

    private void UndoLast()
    {
        if (_undoStack.Count == 0)
        {
            MessageBox.Show(this, "Nothing to undo in this session. Use \"Undo from journal file...\" for an earlier batch.",
                "Batch Rename Studio", MessageBoxButtons.OK, MessageBoxIcon.Information);
            return;
        }

        var journal = _undoStack[^1];
        if (MessageBox.Show(this, "Undo " + journal.Describe() + "?", "Confirm undo",
                MessageBoxButtons.YesNo, MessageBoxIcon.Question) != DialogResult.Yes)
        {
            return;
        }

        _undoStack.RemoveAt(_undoStack.Count - 1);
        _undoButton.Enabled = _undoStack.Count > 0;

        var result = RenameExecutor.Undo(journal);
        ReportResult(result, result.Renamed + " file(s) restored.");

        if (!string.IsNullOrEmpty(journal.Folder))
        {
            LoadFolder(journal.Folder);
        }
    }

    private void UndoFromFile()
    {
        using var dialog = new OpenFileDialog
        {
            Title = "Choose an undo journal",
            Filter = "Journal files (*.json)|*.json|All files (*.*)|*.*",
            InitialDirectory = Directory.Exists(RenameExecutor.JournalDirectory)
                ? RenameExecutor.JournalDirectory
                : Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
        };

        if (dialog.ShowDialog(this) != DialogResult.OK)
        {
            return;
        }

        try
        {
            var journal = RenameExecutor.LoadJournal(dialog.FileName);
            if (journal.Operations.Count == 0)
            {
                MessageBox.Show(this, "That journal has no operations.", "Batch Rename Studio",
                    MessageBoxButtons.OK, MessageBoxIcon.Warning);
                return;
            }

            if (MessageBox.Show(this, "Undo " + journal.Describe() + "?", "Confirm undo",
                    MessageBoxButtons.YesNo, MessageBoxIcon.Question) != DialogResult.Yes)
            {
                return;
            }

            var result = RenameExecutor.Undo(journal);
            ReportResult(result, result.Renamed + " file(s) restored.");
            LoadFolder(journal.Folder);
        }
        catch (Exception ex)
        {
            MessageBox.Show(this, ex.Message, "Batch Rename Studio", MessageBoxButtons.OK, MessageBoxIcon.Error);
        }
    }

    private void OpenJournalFolder()
    {
        try
        {
            Directory.CreateDirectory(RenameExecutor.JournalDirectory);
            System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo
            {
                FileName = RenameExecutor.JournalDirectory,
                UseShellExecute = true,
            });
        }
        catch (Exception ex)
        {
            MessageBox.Show(this, ex.Message, "Batch Rename Studio", MessageBoxButtons.OK, MessageBoxIcon.Error);
        }
    }

    private void ReportResult(RenameResult result, string successText)
    {
        if (result.Succeeded)
        {
            UpdateStatus(successText);
            return;
        }

        string body = string.Join(Environment.NewLine, result.Errors);
        if (result.RolledBack)
        {
            body = "The batch failed and was rolled back." + Environment.NewLine + Environment.NewLine + body;
        }
        MessageBox.Show(this, body, "Batch Rename Studio", MessageBoxButtons.OK, MessageBoxIcon.Error);
        UpdateStatus("Finished with errors.");
    }

    // ---- rule set files ----------------------------------------------------

    private void LoadRules()
    {
        using var dialog = new OpenFileDialog
        {
            Title = "Load rules",
            Filter = "Rule files (*.json)|*.json|All files (*.*)|*.*",
        };
        if (dialog.ShowDialog(this) != DialogResult.OK)
        {
            return;
        }

        try
        {
            var loaded = RuleSetSerializer.ParseFile(dialog.FileName);
            _rules.ApplyTo = loaded.ApplyTo;
            _rules.Sort = loaded.Sort;
            _rules.Steps.Clear();
            _rules.Steps.AddRange(loaded.Steps);

            _applyToCombo.SelectedIndex = _rules.ApplyTo == ApplyTo.NameAndExtension ? 1 : 0;
            _sortCombo.SelectedIndex = (int)_rules.Sort;
            RebuildStepList(_rules.Steps.Count > 0 ? 0 : -1);
            RefreshPreview();
            UpdateStatus("Loaded rules from " + dialog.FileName);
        }
        catch (Exception ex)
        {
            MessageBox.Show(this, ex.Message, "Batch Rename Studio", MessageBoxButtons.OK, MessageBoxIcon.Error);
        }
    }

    private void SaveRules()
    {
        using var dialog = new SaveFileDialog
        {
            Title = "Save rules",
            Filter = "Rule files (*.json)|*.json",
            FileName = "rules.json",
        };
        if (dialog.ShowDialog(this) != DialogResult.OK)
        {
            return;
        }

        try
        {
            File.WriteAllBytes(dialog.FileName,
                System.Text.Encoding.UTF8.GetBytes(RuleSetSerializer.Write(_rules) + "\n"));
            UpdateStatus("Saved rules to " + dialog.FileName);
        }
        catch (Exception ex)
        {
            MessageBox.Show(this, ex.Message, "Batch Rename Studio", MessageBoxButtons.OK, MessageBoxIcon.Error);
        }
    }

    private void ExportPlan()
    {
        if (string.IsNullOrEmpty(_folder))
        {
            MessageBox.Show(this, "Load a folder first.", "Batch Rename Studio",
                MessageBoxButtons.OK, MessageBoxIcon.Information);
            return;
        }

        using var dialog = new SaveFileDialog
        {
            Title = "Export plan",
            Filter = "Plan files (*.json)|*.json",
            FileName = "plan.json",
        };
        if (dialog.ShowDialog(this) != DialogResult.OK)
        {
            return;
        }

        try
        {
            PlanSerializer.WriteFile(_plan, dialog.FileName);
            UpdateStatus("Exported plan to " + dialog.FileName);
        }
        catch (Exception ex)
        {
            MessageBox.Show(this, ex.Message, "Batch Rename Studio", MessageBoxButtons.OK, MessageBoxIcon.Error);
        }
    }

    private void ShowAbout()
    {
        MessageBox.Show(this,
            "Batch Rename Studio\n\n"
            + "Preview-first batch renaming for Windows.\n"
            + "The preview you see is produced by the same planner as\n"
            + "  BatchRenameStudio.exe --plan --dir <folder> --rules <rules.json> --out <plan.json>\n\n"
            + "Undo journals live in:\n" + RenameExecutor.JournalDirectory,
            "About", MessageBoxButtons.OK, MessageBoxIcon.Information);
    }

    protected override void Dispose(bool disposing)
    {
        if (disposing)
        {
            _debounce.Dispose();
        }
        base.Dispose(disposing);
    }
}

