using System.Runtime.InteropServices;
using System.Text;

namespace BatchRenameStudio.Cli;

/// <summary>
/// The executable is a WinExe so that launching it from Explorer never flashes a console
/// window. That means a run started from an interactive shell has no console of its own, and
/// Console.Out would go nowhere. Attaching to the parent console fixes the interactive case
/// while leaving a redirected stdout (the way an automated caller runs us) completely alone.
/// </summary>
internal static class ConsoleBridge
{
    private const int StdOutputHandle = -11;
    private const int StdErrorHandle = -12;
    private const int AttachParentProcess = -1;

    private static bool _attached;

    public static void Attach()
    {
        if (_attached)
        {
            return;
        }
        _attached = true;

        if (!OperatingSystem.IsWindows())
        {
            return;
        }

        // A valid handle means the caller already gave us somewhere to write (a pipe, a file,
        // or an inherited console). Touching the console in that case would only break it.
        if (HasHandle(StdOutputHandle) && HasHandle(StdErrorHandle))
        {
            return;
        }

        if (!AttachConsole(AttachParentProcess))
        {
            return;
        }

        try
        {
            var stdout = new StreamWriter(Console.OpenStandardOutput(), new UTF8Encoding(false))
            {
                AutoFlush = true,
            };
            Console.SetOut(stdout);

            var stderr = new StreamWriter(Console.OpenStandardError(), new UTF8Encoding(false))
            {
                AutoFlush = true,
            };
            Console.SetError(stderr);
        }
        catch (IOException)
        {
            // No usable console after all - stay silent rather than crash a headless run.
        }
    }

    private static bool HasHandle(int which)
    {
        IntPtr handle = GetStdHandle(which);
        return handle != IntPtr.Zero && handle != new IntPtr(-1);
    }

    [DllImport("kernel32.dll", SetLastError = true)]
    [return: MarshalAs(UnmanagedType.Bool)]
    private static extern bool AttachConsole(int processId);

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern IntPtr GetStdHandle(int nStdHandle);
}

