/// <summary>
/// Releases the console the OS handed us before the window appears. When the program was
/// started from an existing shell the console belongs to that shell, and detaching leaves
/// it untouched; when it was started from Explorer the freshly allocated window goes away.
/// </summary>
public static void DetachForGui()
{
    if (!OperatingSystem.IsWindows())
    {
        return;
    }

    try
    {
        IntPtr window = GetConsoleWindow();
        if (window != IntPtr.Zero)
        {
            ShowWindow(window, SwHide);
        }
        FreeConsole();
    }
    catch (EntryPointNotFoundException)
    {
        // Nothing to release; the GUI does not need a console either way.
    }
}

