using System.Reflection;
using BatchRenameStudio.Cli;
using BatchRenameStudio.Ui;

namespace BatchRenameStudio;

internal static class Program
{
    [STAThread]
    private static int Main(string[] args)
    {
        var options = CommandLine.Parse(args);

        switch (options.Mode)
        {
            case CliMode.Plan:
                ConsoleBridge.Attach();
                return HeadlessRunner.RunPlan(options);

            case CliMode.Apply:
                ConsoleBridge.Attach();
                return HeadlessRunner.RunApply(options);

            case CliMode.Help:
                ConsoleBridge.Attach();
                Console.Out.WriteLine(CommandLine.Usage);
                return 0;

            case CliMode.Version:
                ConsoleBridge.Attach();
                Console.Out.WriteLine(VersionString());
                return 0;

            case CliMode.Error:
                ConsoleBridge.Attach();
                Console.Error.WriteLine("error: " + options.ErrorMessage);
                Console.Error.WriteLine();
                Console.Error.WriteLine(CommandLine.Usage);
                return HeadlessRunner.ExitFailure;

            default:
                return RunGui(options);
        }
    }

    private static int RunGui(CliOptions options)
    {
        Application.EnableVisualStyles();
        Application.SetCompatibleTextRenderingDefault(false);
        Application.SetHighDpiMode(HighDpiMode.PerMonitorV2);
        Application.Run(new MainForm(options.Directory));
        return 0;
    }

    private static string VersionString()
    {
        var version = Assembly.GetExecutingAssembly().GetName().Version;
        return "Batch Rename Studio " + (version?.ToString(3) ?? "1.0.0");
    }
}

