                return Fail(options, "--apply renames files; pass --yes to confirm.");
            }
            return options;
        }

        options.Mode = CliMode.Gui;
        return options;
    }

    private static bool TakeValue(string[] args, ref int index, string? inlineValue, out string value)
    {
        if (inlineValue is not null)
        {
            value = inlineValue;
            return value.Length > 0;
        }

        if (index + 1 >= args.Length)
        {
            value = string.Empty;
            return false;
        }

        index++;
        value = args[index];
        return true;
    }

    private static CliOptions Fail(CliOptions options, string message)
    {
        options.Mode = CliMode.Error;
        options.ErrorMessage = message;
        return options;
    }
}

